import unittest
from capture_rows import *
class CaptureRows(unittest.TestCase):
    def test_capture_dependent_shape(self):
        rows=[(r'[A-Z]+','oak AB pine CD',['AB','CD']),(r'item=(\d+)','item=12 item=7',['12','7']),(r'([a-z]+)=(\d+)','oak=12 elm=7',[('oak','12'),('elm','7')]),(r'([A-Z])([0-9])','A1 B2',[('A','1'),('B','2')]),(r'(?:(a)|(b))','ab',[('a',''),('','b')]),(r'(?:[a-z]+)=([0-9]+)','oak=12',['12']),(r'x*','a',['','']),(r'(x)?y','y xy',['','x']),(r'(?=a)','aa',['','']),(r'([a-z]+)=(\d+)','none',[])]
        for pattern,text,expected in rows:
            with self.subTest(pattern=pattern,text=text):
                self.assertEqual(capture_rows(pattern,text),expected)

if __name__ == '__main__':
    unittest.main()

